class TreeTraversal {
  dfs(node: any, callback: (n: any) => void) {
    callback(node);
    if (node.children) node.children.forEach((c: any) => this.dfs(c, callback));
  }
  bfs(root: any, callback: (n: any) => void) {
    const queue = [root];
    while (queue.length) {
      const node = queue.shift();
      callback(node);
      if (node.children) queue.push(...node.children);
    }
  }
}

